// The payload must come from the trigger, not from $input: 'Auth OK?' sits
// in between, so $input here is the Supabase user object, not the request.
// $('Webhook - Ask AI') THROWS if that node did not run in this execution --
// it does NOT return undefined -- so the lookup is wrapped in try/catch.
let raw;
try {
  raw = $('Webhook - Ask AI').first().json;
} catch (e) {
  raw = $input.first().json;   // direct / sub-workflow call
}

const body = raw.body || raw;
const question = String(body.question || body.query || body.q || '').trim();

if (!question) {
  throw new Error('No question provided. POST a JSON body like { "question": "What is our warranty policy?" }');
}

// Retrieval now lives in Postgres: public.search_rag_documents(q, match_limit).
// It ranks with ts_rank_cd and falls back to per-term trigram matching for
// typos. This node no longer builds a tsquery or strips stopwords -- doing
// that here is exactly what made short questions return nothing.
return [{ json: { question } }];

const question = $('Extract Question').first().json.question;

// search_rag_documents returns a ranked array; n8n splits it one item per row.
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.content);

let context = '';
const sources = [];

rows.forEach((doc, i) => {
  const title = doc.doc_title || 'Document';
  const section = doc.section ? ` / ${doc.section}` : '';
  context += `[Source ${i + 1}] ${title}${section}:\n${doc.content}\n\n`;
  sources.push({
    title: title,
    section: doc.section || null,
    source_file: doc.source_file || null,
    page_number: doc.page_number ?? null,
    match_type: doc.match_type || null,
    rank: doc.rank ?? null
  });
});

// Nothing matched. Carry a message the user can act on -- the old build fell
// through with an empty answer and the dashboard rendered "No answer returned."
const no_match = rows.length === 0;
if (no_match) {
  context = 'No relevant documents were found in the knowledge base for this question.';
}

return [{ json: {
  question,
  context: context.substring(0, 8000),
  sources,
  doc_count: sources.length,
  no_match,
  no_match_message: 'Nothing in the knowledge base matched that. It currently covers the warranty policy, the HR handbook, sales compensation and the trade-in appraisal SOP - try asking in a full sentence, for example "What is our warranty on a new car?"'
} }];

const aiResponse = $input.first().json;
const context = $('Build RAG Context').first().json;

let answer;
if (context.no_match) {
  // Deterministic: never hand the dashboard an empty answer.
  answer = context.no_match_message;
} else if (aiResponse.error) {
  answer = 'The AI model call failed: ' + JSON.stringify(aiResponse.error).substring(0, 300);
} else if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message
           && String(aiResponse.choices[0].message.content || '').trim()) {
  answer = aiResponse.choices[0].message.content;
} else {
  answer = 'The model returned an empty answer even though ' + context.doc_count
         + ' document(s) matched. Please try rephrasing the question.';
}

return [{ json: {
  question: context.question,
  answer: answer,
  sources: context.sources,
  documents_consulted: context.doc_count,
  no_match: !!context.no_match,
  model: aiResponse.model || null,
  timestamp: new Date().toISOString()
} }];

// Verify every node whose success this audit row is about to claim.
// 'Respond to Webhook' swallows with onError: continueRegularOutput: if the
// response never reaches the caller the run still carries on to 'Audit Log'.
// The model call is NOT claimed here - 'AI Agent - Generate Answer' uses
// continueErrorOutput and its error output is routed to
// 'AI Answer - Backup Models', so a primary failure is handled, not swallowed,
// and 'Format Response' already puts a model failure into the answer text.
const CLAIMED = [
  { node: 'Respond to Webhook', what: 'HTTP answer returned to the caller', critical: true },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);
const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

const base = $input.first().json || {};

// When the respond node drops, its output item is the error rather than the
// passed-through payload, so question/documents_consulted vanish and the audit
// summary would read 'Q: undefined'. Recover them from 'Format Response'.
let fr = {};
try { fr = $('Format Response').first().json || {}; } catch (e) { fr = {}; }

return [{ json: {
  ...base,
  question: base.question !== undefined ? base.question : (fr.question ?? null),
  documents_consulted: base.documents_consulted !== undefined ? base.documents_consulted : (fr.documents_consulted ?? null),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' - ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
} }];

